  function resourceCapacityHtml(){const rows=capacityRows();return `<div class="section-title"><h2>${tr('BPO / SME capacity','Capacité BPO / SME')}</h2><span>${tr('160h/month × project capacity %; task-hour estimates drive load','160 h/mois × % de capacité projet; les estimations d’heures alimentent la charge')}</span></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>${tr('Person','Personne')}</th><th>${tr('Role / stream','Rôle / chaîne')}</th><th>${tr('Project capacity','Capacité projet')}</th><th>${tr('Estimated next 30d','Estimé 30 prochains jours')}</th><th>${tr('Load','Charge')}</th><th>${tr('Unestimated tasks','Tâches non estimées')}</th></tr></thead><tbody>${rows.map(x=>{const p=people().find(z=>z.name===x.owner);return `<tr><td><b>${esc(x.owner)}</b></td><td>${esc(p?.role||'')} · ${esc(p?.stream||'')}</td><td>${x.capacityPct}% · ${Math.round(x.available)}h</td><td>${Math.round(x.hours)}h</td><td>${x.hours?statusPill(`${Math.round(x.load)}%`):'—'}</td><td>${x.unestimated?statusPill(String(x.unestimated)):0}</td></tr>`}).join('')}</tbody></table><div class="v9-footnote">${tr('Capacity is only considered reliable once active tasks have Estimated hours. The dashboard does not invent task-hour estimates.','La capacité est fiable seulement lorsque les tâches actives ont des heures estimées. Le tableau de bord n’invente pas d’estimations.')}</div></div>`}
  function entityDesignSummaryHtml(){const xs=rawReg('entityDesign');return `<div class="section-title"><h2>${tr('Entity design matrix','Matrice de conception par entité')}</h2><button class="btn primary" id="v9AddEntityDesign">+ ${tr('Design delta','Écart de conception')}</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>${tr('Topic','Sujet')}</th><th>L1 / L2 / L3</th><th>IFAST</th><th>Infasco</th><th>Infasco Nut</th><th>DSI</th><th>${tr('Disposition','Disposition')}</th><th>${tr('Owner','Responsable')}</th></tr></thead><tbody>${xs.map(x=>`<tr data-v9-entity-design="${esc(x.id)}"><td><b>${esc(x.topic||'')}</b></td><td>${esc([x.stream,x.l2,x.l3ProcessId].filter(Boolean).join(' › '))}</td><td>${esc(x.ifastStandard||'')}</td><td>${esc(x.infasco||'')}</td><td>${esc(x.infascoNut||'')}</td><td>${esc(x.dsi||'')}</td><td>${statusPill(x.disposition||'TBD')}</td><td>${esc(x.owner||'')}</td></tr>`).join('')}</tbody></table>${xs.length?'':`<div class="empty">${tr('No entity design differences documented yet. Add differences only when a common IFAST design cannot be used.','Aucun écart de conception entre entités n’est encore documenté. Ajouter un écart seulement lorsqu’un design IFAST commun ne peut pas être utilisé.')}</div>`}</div>`}
