  function testingHtml(){const tests=scopedRaw('testScenarios'),cut=scopedRaw('cutoverItems'),sit=tests.filter(x=>x.testType==='SIT'),uat=tests.filter(x=>x.testType==='UAT');const testTable=`<div class="section-title"><h2>${tr('Testing command center','Centre de contrôle des tests')}</h2><button class="btn primary" id="v9AddTest">+ ${tr('Test scenario','Scénario de test')}</button></div><div class="v9-test-kpis"><div class="card"><span>SIT</span><b>${sit.filter(x=>x.status==='Passed').length}/${sit.length}</b><small>${tr('passed','réussis')}</small></div><div class="card"><span>UAT</span><b>${uat.filter(x=>x.status==='Passed').length}/${uat.length}</b><small>${tr('passed','réussis')}</small></div><div class="card"><span>${tr('Blocked / failed','Bloqués / échoués')}</span><b>${tests.filter(x=>['Blocked','Failed'].includes(x.status)).length}</b></div><div class="card"><span>${tr('Critical scenarios','Scénarios critiques')}</span><b>${tests.filter(x=>x.criticality==='Critical').length}</b></div></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>${tr('Scenario','Scénario')}</th><th>${tr('Type','Type')}</th><th>${tr('Process','Processus')}</th><th>${tr('Entity','Entité')}</th><th>${tr('Owner','Responsable')}</th><th>${tr('Requirement','Exigence')}</th><th>${tr('Status','Statut')}</th></tr></thead><tbody>${tests.map(x=>`<tr data-v9-test="${esc(x.id)}"><td>${esc(x.id)}</td><td><b>${esc(x.scenario)}</b><small>${esc(x.evidence||'')}</small></td><td>${esc(x.testType||'SIT')}</td><td>${esc([x.stream,x.l2,x.l3ProcessId].filter(Boolean).join(' › '))}</td><td>${esc(x.entityScope||'All entities')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.linkedRequirement||'')}</td><td>${statusPill(x.status||'Not Started')}</td></tr>`).join('')}</tbody></table>${tests.length?'':`<div class="empty">${tr('No SIT/UAT scenarios documented yet.','Aucun scénario SIT/UAT documenté.')}</div>`}</div>`;
    const cutTable=`<div class="section-title"><h2>${tr('Cutover & operational readiness','Bascule et préparation opérationnelle')}</h2><button class="btn primary" id="v9AddCutover">+ ${tr('Readiness item','Élément de préparation')}</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>${tr('Category','Catégorie')}</th><th>${tr('Readiness item','Élément')}</th><th>${tr('Entity','Entité')}</th><th>${tr('Owner','Responsable')}</th><th>${tr('Due','Échéance')}</th><th>${tr('Evidence','Preuve')}</th><th>${tr('Status','Statut')}</th></tr></thead><tbody>${cut.map(x=>`<tr data-v9-cutover="${esc(x.id)}"><td>${esc(x.id)}</td><td>${esc(x.category||'Cutover')}</td><td><b>${esc(x.title)}</b></td><td>${esc(x.entityScope||'All entities')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.due||'')}</td><td>${esc(x.evidence||'')}</td><td>${statusPill(x.status||'Not Started')}</td></tr>`).join('')}</tbody></table>${cut.length?'':`<div class="empty">${tr('No cutover/readiness items documented yet.','Aucun élément de bascule/préparation documenté.')}</div>`}</div>`;return testTable+cutTable}
