  function steeringPack(){const d=data(),conf=deliveryConfidence(),m=conf.milestone,ex=exceptions(),dec=(d.decisions||[]).filter(x=>(x.escalateToSteering===true||x.escalateToSteering==='Yes'||x.status==='Recommended')&&!['Closed','Decided'].includes(x.status)),escs=(d.escalations||[]).filter(x=>!['Closed','Resolved'].includes(x.status)),changes=scopedRaw('changeRequests').filter(x=>['Decision Required','Submitted','Analysis'].includes(x.status)),over=capacityRows().filter(x=>x.load>100),entity=rawReg('entityDesign').filter(x=>['TBD','Open'].includes(x.status||x.disposition));return `<div class="v9-steering-pack"><div class="v9-steer-banner"><div><span>${tr('PROGRAM CONFIDENCE','CONFIANCE PROGRAMME')}</span><b>${esc(conf.label)}</b></div><div><span>${tr('CURRENT GATE','JALON ACTUEL')}</span><b>${esc(m?.id||'—')} · ${Math.round(conf.gate)}%</b></div><div><span>${tr('DECISIONS REQUIRED','DÉCISIONS REQUISES')}</span><b>${dec.length+escs.length}</b></div><div><span>${tr('HIGH / CRITICAL EXCEPTIONS','EXCEPTIONS ÉLEVÉES / CRITIQUES')}</span><b>${conf.high+conf.critical}</b></div></div><div class="section-title"><h2>${tr('Decision agenda','Ordre du jour décisionnel')}</h2><span>${tr('Every item should state the ask, recommendation and impact','Chaque élément doit préciser la demande, la recommandation et l’impact')}</span></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>${tr('Ask / decision','Demande / décision')}</th><th>${tr('Recommendation','Recommandation')}</th><th>${tr('Impact','Impact')}</th><th>${tr('Owner','Responsable')}</th><th>${tr('Date','Date')}</th></tr></thead><tbody>${[...escs.map(x=>({title:x.title,rec:x.recommendation,impact:x.reason||x.impact,owner:x.owner,date:x.committeeDate||x.due})),...dec.map(x=>({title:x.requestedDecision||x.title,rec:x.recommendation,impact:[x.businessImpact,x.financialImpact,x.scheduleImpact,x.riskImpact].filter(Boolean).join(' · '),owner:x.owner,date:x.committeeDate||x.due}))].map(x=>`<tr><td><b>${esc(x.title||'')}</b></td><td>${esc(x.rec||'')}</td><td>${esc(x.impact||'')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.date||'TBD')}</td></tr>`).join('')}</tbody></table>${dec.length+escs.length?'':`<div class="empty">${tr('No decisions currently require Steering Committee action.','Aucune décision ne requiert actuellement l’action du comité directeur.')}</div>`}</div><div class="grid three-col v9-steer-summary"><div class="card pad"><h3>${tr('Top program exceptions','Principales exceptions')}</h3>${ex.slice(0,5).map(x=>`<div class="v9-list-row">${statusPill(x.sev)}<span><b>${esc(x.type)}</b><small>${esc(x.title)}</small></span></div>`).join('')||'<div class="empty mini">—</div>'}</div><div class="card pad"><h3>${tr('Scope / entity decisions','Portée / décisions entités')}</h3><p><b>${changes.length}</b> ${tr('open scope changes','changements de portée ouverts')}</p><p><b>${entity.length}</b> ${tr('entity design deltas unresolved','écarts de conception entités non résolus')}</p></div><div class="card pad"><h3>${tr('Resource constraints','Contraintes de ressources')}</h3>${over.slice(0,5).map(x=>`<p><b>${esc(x.owner)}</b><small>${Math.round(x.load)}% ${tr('estimated load','charge estimée')}</small></p>`).join('')||`<div class="empty mini">${tr('No measured overloads.','Aucune surcharge mesurée.')}</div>`}</div></div></div>`}
